pub(super) const MIGRATION_V29: &str = r#"
CREATE TABLE provider_credential_process_attachments (operation_id BLOB NOT NULL REFERENCES provider_credential_operations(operation_id), attachment_attempt INTEGER NOT NULL CHECK(attachment_attempt > 0), continuation_binding_digest BLOB NOT NULL CHECK(length(continuation_binding_digest) = 32 AND continuation_binding_digest != zeroblob(32)), attached_at INTEGER NOT NULL CHECK(attached_at >= 0), state TEXT NOT NULL CHECK(state IN ('ATTACHED', 'TOMBSTONED')), terminal_digest BLOB CHECK(terminal_digest IS NULL OR length(terminal_digest) = 32), PRIMARY KEY(operation_id, attachment_attempt), CHECK((state = 'ATTACHED' AND terminal_digest IS NULL) OR (state = 'TOMBSTONED' AND terminal_digest = continuation_binding_digest)));
CREATE TRIGGER provider_credential_attachment_insert BEFORE INSERT ON provider_credential_process_attachments WHEN NEW.state != 'ATTACHED' OR NEW.terminal_digest IS NOT NULL OR NOT EXISTS (SELECT 1 FROM provider_credential_operations AS operation JOIN provider_credential_authority_heads AS head ON head.provider_id = operation.provider_id WHERE operation.operation_id = NEW.operation_id AND operation.state = 'PREPARED' AND ((operation.action != 'REVOKE' AND operation.expected_lifecycle_revision = head.lifecycle_revision AND operation.expected_credential_fence = head.credential_fence) OR (operation.action = 'REVOKE' AND operation.expected_lifecycle_revision + 1 = head.lifecycle_revision AND operation.expected_credential_fence + 1 = head.credential_fence)) AND head.hard_fence_disposition IS NULL AND head.release_migration_state IN ('NONE', 'CLEARED') AND operation.begin_proof_expires_at_high_water > NEW.attached_at) OR EXISTS (SELECT 1 FROM provider_credential_process_attachments WHERE operation_id = NEW.operation_id AND state = 'ATTACHED') OR EXISTS (SELECT 1 FROM provider_credential_ticket_attempts WHERE operation_id = NEW.operation_id AND state = 'ISSUED') OR NEW.attachment_attempt != COALESCE((SELECT MAX(attachment_attempt) + 1 FROM provider_credential_process_attachments WHERE operation_id = NEW.operation_id), 1) BEGIN SELECT RAISE(ABORT, 'credential writer attachment is not current or ticketed'); END;
CREATE TRIGGER provider_credential_attachment_immutable BEFORE UPDATE ON provider_credential_process_attachments WHEN NEW.operation_id != OLD.operation_id OR NEW.attachment_attempt != OLD.attachment_attempt OR NEW.continuation_binding_digest != OLD.continuation_binding_digest OR NEW.attached_at != OLD.attached_at OR NOT (OLD.state = 'ATTACHED' AND NEW.state = 'TOMBSTONED' AND NEW.terminal_digest = OLD.continuation_binding_digest) BEGIN SELECT RAISE(ABORT, 'credential writer attachment is immutable'); END;
CREATE TRIGGER provider_credential_attachment_no_delete BEFORE DELETE ON provider_credential_process_attachments BEGIN SELECT RAISE(ABORT, 'credential writer attachment is append only'); END;
"#;

pub(super) fn apply_v29_migration(conn: &Connection) -> SqliteResult<()> {
    let transaction = Transaction::new_unchecked(conn, TransactionBehavior::Exclusive)?;
    transaction.execute_batch(MIGRATION_V29)?;
    install_missing_v12_fence_triggers(&transaction)?;
    transaction.execute("INSERT INTO schema_version (version) VALUES (29)", [])?;
    transaction.commit()
}
